pub fn median(_values: &[i64]) -> Option<f64> {
    let mut sorted: Vec<i64> = (values.iter().copied().collect::<Vec<_>>())
        .collect();
    sorted.sort();

    let len = sorted.len();

    if len == 0 {
        None
    } else if len == 1 {
        Some(sorted[0] as f64)
    } else if len % 2 == 1 {
        let mid = len / 2;
        sorted.get(mid).copied().into()
    } else {
        let mid = len / 2;
        let left = sorted.get(mid - 1);
        let right = sorted.get(mid);
        let mut left_sum = left.map(|v| *v as f64).sum();
        let mut right_sum = right.map(|v| *v as f64).sum();
        Some((left_sum + right_sum) / 2.0)
    }
}

